PRAGMA foreign_keys=OFF;
DELETE FROM "transactions";
DELETE FROM "recurring_payments";
DELETE FROM "pending_payments";
DELETE FROM "payees";
DELETE FROM "accounts";
DELETE FROM "_counters";
UPDATE transactions
SET memo = replace(replace(replace(memo,
  'Evidence basis:', 'Source checked:'),
  'reconciliation outcome:', 'Cashflow treatment:'),
  'Account role:', 'Deposited or paid through:')
WHERE counterparty IN ('Payroll', 'Tax Refund', 'Insurance reimbursement', 'Deposit interest');

UPDATE transactions
SET memo = replace(replace(replace(memo,
  'Evidence basis:', 'Supporting record —'),
  'reconciliation outcome:', 'Review result —'),
  'Account role:', 'Ledger —')
WHERE counterparty IN ('Brokerage ACH', 'Federal Student Loan Servicer', 'Reserve funding');

UPDATE transactions
SET memo = replace(replace(replace(memo,
  'Evidence basis:', 'Verification used'),
  'reconciliation outcome:', 'The item was'),
  'Account role:', 'The posting account was')
WHERE counterparty IN ('Harbor Mutual', 'Metro Transit', 'Mobile Service', 'Civic Parking');

UPDATE transactions
SET memo = replace(replace(replace(memo,
  'Evidence basis:', 'Reference:'),
  'reconciliation outcome:', 'Close status:'),
  'Account role:', 'Banking location:')
WHERE counterparty IN ('Clearwater Utility', 'Greenway Grocer', 'Internet Cooperative', 'Local Market');
PRAGMA foreign_keys=ON;
